SELECT order_id, CAST(format_datetime(at_timezone(order_date, current_timezone()), 'yyyyMMdd') AS INTEGER) AS created_date_key, CAST(format_datetime(at_timezone(delivery_date, current_timezone()), 'yyyyMMdd') AS INTEGER) AS delivery_date_key, 'craft:client:' || CAST(client_id AS VARCHAR) AS client_key, 'craft:master:' || CAST(master_id AS VARCHAR) AS master_key, 'craft:product:' || CAST(product_id AS VARCHAR) AS product_key, CASE status WHEN 'in progress' THEN 'in_progress' ELSE status END AS status_code, order_date, delivery_date, order_price, paid_at FROM lake.stg.pg_public_order WHERE batch_id = '{{batch_id}}'
